  EFS: ['Elastic File System', 'Managed NFS file storage shared across many instances and AZs.'],
  S3: ['Simple Storage Service', 'AWS object storage: unlimited, durable buckets of files.'],
  RDS: ['Relational Database Service', 'Managed SQL databases (MySQL, PostgreSQL, etc.) with backups and Multi-AZ failover.'],
  DAX: ['DynamoDB Accelerator', 'An in-memory cache for DynamoDB with microsecond reads.'],
  SQS: ['Simple Queue Service', 'Managed message queues that decouple producers from consumers.'],
  SNS: ['Simple Notification Service', 'Pub/sub messaging that fans one message out to many subscribers.'],
