  STS: ['Security Token Service', 'Issues short-lived AWS credentials when you assume a role.'],
  SCP: ['Service Control Policy (also Secure Copy Protocol)', 'AWS: an Organizations guardrail capping what accounts can do. Linux: file copy over SSH.'],
  'SSE-S3': ['Server-Side Encryption with S3-managed keys', 'S3 encrypts objects with keys AWS fully manages; the default.'],
  'SSE-KMS': ['Server-Side Encryption with KMS keys', 'S3 encryption with KMS keys you control, plus audit trail and key policies.'],
  'SSE-C': ['Server-Side Encryption with Customer-provided keys', 'You send the key with each request; AWS never stores it.'],
  ASFF: ['AWS Security Finding Format', 'The standard JSON schema Security Hub uses for findings.'],
  IRSA: ['IAM Roles for Service Accounts', 'Gives Kubernetes pods on EKS their own least-privilege AWS role.'],
  OAC: ['Origin Access Control', 'Lets only CloudFront read a private S3 bucket.'],
  EMR: ['Elastic MapReduce', 'AWS-managed big data clusters (Spark, Hadoop).'],
  DMS: ['Database Migration Service', 'Migrates databases to AWS with minimal downtime.'],
  IOPS: ['Input/Output Operations Per Second', 'A storage performance measure; key for database volumes.'],
  'SCS-C02': ['AWS Certified Security - Specialty exam code', 'The current exam version of the AWS Security Specialty certification.'],
  'SAA-C03': ['AWS Certified Solutions Architect - Associate exam code', 'The current exam version of the AWS Solutions Architect Associate certification.'],
  'SY0-701': ['CompTIA Security+ exam code', 'The current Security+ exam version.'],
