const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Longest keys first so "SSE-KMS" beats "SSE" and "CI/CD" beats "CI".
const KEYS = Object.keys(ACRONYMS).sort((a, b) => b.length - a.length);

// Not glued to letters/digits on either side; allows a plural "s" (APIs, VPCs).
const ACRONYM_RE = new RegExp(`(?<![A-Za-z0-9])(${KEYS.map(escapeRe).join('|')})(s)?(?![A-Za-z0-9])`, 'g');

// Text that asks what an acronym stands for must not reveal the answer.
const GIVEAWAY_RE = /\bstands?\s+for\b/i;

/** Every glossary acronym in `text`, as { key, start, end } (end exclusive, includes a plural "s"). */
export function findAcronyms(text) {
  if (!text || text.length < 2 || GIVEAWAY_RE.test(text)) return [];
  const out = [];
  ACRONYM_RE.lastIndex = 0;
  let m;
  while ((m = ACRONYM_RE.exec(text))) {
    out.push({ key: m[1], start: m.index, end: m.index + m[0].length });
  }
  return out;
}

/** { term, expansion, purpose } for a glossary key, or null. */
export function lookupAcronym(key) {
  const entry = ACRONYMS[key];
  return entry ? { term: key, expansion: entry[0], purpose: entry[1] } : null;
}
